import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";

function ProductDetails() {
  const { id } = useParams();

  const [product, setProduct] = useState({});
  const [selectedSize, setSelectedSize] = useState("M");
  const [selectedColor, setSelectedColor] = useState("white");

  // 🔹 Load product from backend
  useEffect(() => {
    fetch(`http://localhost:8080/api/products/${id}`)
      .then(res => res.json())
      .then(data => setProduct(data));
  }, [id]);

  // 🔹 Add to cart
  const addToCart = () => {
    const cartItem = {
      ...product,
      size: selectedSize,
      color: selectedColor,
    };

    let cart = JSON.parse(localStorage.getItem("cart")) || [];
    cart.push(cartItem);
    localStorage.setItem("cart", JSON.stringify(cart));

    alert("Added to cart!");
  };

  return (
    <div className="pt-16 pb-32 max-w-7xl mx-auto px-4">
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">

        {/* IMAGE SECTION */}
        <div className="lg:col-span-7">
          <div className="aspect-[3/4] bg-gray-100 rounded-lg overflow-hidden">
            <img
              src={product.image || "https://via.placeholder.com/400"}
              alt={product.name}
              className="w-full h-full object-cover"
            />
          </div>
        </div>

        {/* DETAILS SECTION */}
        <div className="lg:col-span-5">

          <h1 className="text-2xl font-semibold mb-2">
            {product.name}
          </h1>

          <p className="text-lg mb-4">
            ${product.price}
          </p>

          {/* COLOR */}
          <div className="mb-6">
            <p className="text-sm mb-2">Select Color</p>
            <div className="flex gap-2">
              {["white", "beige", "black", "green"].map(color => (
                <button
                  key={color}
                  onClick={() => setSelectedColor(color)}
                  className={`w-8 h-8 rounded-full border ${
                    selectedColor === color ? "border-black" : ""
                  }`}
                  style={{ backgroundColor: color }}
                />
              ))}
            </div>
          </div>

          {/* SIZE */}
          <div className="mb-6">
            <p className="text-sm mb-2">Select Size</p>
            <div className="grid grid-cols-4 gap-2">
              {["S", "M", "L", "XL"].map(size => (
                <button
                  key={size}
                  onClick={() => setSelectedSize(size)}
                  className={`py-2 border rounded ${
                    selectedSize === size
                      ? "border-black font-bold"
                      : ""
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          {/* ADD TO CART */}
          <button
            onClick={addToCart}
            className="w-full bg-black text-white py-3 rounded mb-6"
          >
            Add to Bag
          </button>

          {/* DETAILS */}
          <div>
            <h3 className="font-semibold mb-2">Details</h3>
            <p className="text-sm text-gray-600">
              {product.description || "No description available"}
            </p>
          </div>

        </div>
      </div>
    </div>
  );
}

export default ProductDetails;
